def minCostConnectPoints(points):
    n = len(points)
    INF = float('inf')
    d = [INF] * n
    d[0] = 0
    used = [False] * n
    total = 0
    for _ in range(n):
        u = -1
        for i in range(n):
            if not used[i] and (u == -1 or d[i] < d[u]):
                u = i
        used[u] = True
        total += d[u]
        ux, uy = points[u]
        for v in range(n):
            if not used[v]:
                w = abs(ux - points[v][0]) + abs(uy - points[v][1])
                if w < d[v]:
                    d[v] = w
    return total
